async function check(name,fn){await fn();checks++;console.log(`PASS: ${name}`);}
async function actor(role,id){await db.query('reset role');await db.query("select set_config('request.jwt.claim.sub',$1,true),set_config('request.jwt.claims',$2,true)",[id??'',JSON.stringify({sub:id,role})]);await db.query(`set local role ${role}`);}
async function rejected(fn){await db.query('savepoint reject_test');let denied=false;try{await fn();}catch{denied=true;}await db.query('rollback to savepoint reject_test');assert.equal(denied,true,'Expected database rejection');}
async function rpc(name,args){const {rows}=await db.query(`select public.${name}(${args.map((_,i)=>`$${i+1}`).join(',')}) result`,args.map(v=>Array.isArray(v)?JSON.stringify(v):v));return rows[0].result;}
